For $r$ a positive integer, and $d$ an odd positive integer,
a presentation for the integral Chow ring of the stack $\mathcal M_{0}(\mathbb P^r, d)$ is given by:
\begin{equation*}
 A^\ast(\mathcal M_{0}(\mathbb P^r, d)) = \frac{\mathbb Z[c_1,c_2]}{(\alpha^{r,d}_{i,k})_{i,k}},
 \end{equation*}
 where $c_i$ is a graded variable of degree $i$ and $\alpha_{i,k}^{r,d}$ is homogeneous of degree $ir+k$ (Thm. \ref{thmheresthepres}); in order to generate the ideal of relations it is sufficient to consider the following values for $i,k$ (Thm. \ref{ideal.of.relations}):
 \begin{itemize}
     \item $i = 1$ and $k = 0,1$.
     \item $i$ is a prime power and $k = 0$.
 \end{itemize}

 \noindent The generating relations are exhibited in generating function form, where: $$\mathcal{A}_{i,k}(d) := \sum_{r=0}^{\infty} \alpha_{i,k}^{r,d}.$$

\noindent Relations of the form $\alpha^{r,d}_{1,k}$ are explicitly computed in Theorem \ref{thm:genfunctionsforfirstenveloperelations}:
 \begin{equation*}
  \mathcal{A}_{1,0}(d)  = \frac{d}{(1+\frac{d-1}{2}c_1)(1-\frac{d+1}{2}c_1)+d^2c_2} 
\end{equation*}
\begin{equation*}
 \mathcal{A}_{1,1}(d)  = \frac{1+\frac{d-1}{2}c_1}{(1+\frac{d-1}{2}c_1)(1-\frac{d+1}{2}c_1)+d^2c_2}-1.   
\end{equation*}

\noindent Relations of the form $\alpha^{r,d}_{i,0}$ are computed in Theorem \ref{thm:degszero} as:
\begin{equation*}
 \mathcal{A}_{i,0}(d)=
     \displaystyle \sum_{j=0}^{i} \frac{(-1)^{j}}{i! (l_1-l_2)^i}\binom{i}{j}\left[\left(1-\frac{\prod_{k = 0}^{d}\left(\frac{c_1}{2}+\left(k-\frac{d}{2}\right)(l_1-l_2) \right)}
     {\prod_{k = j}^{d-i+j}\left(\frac{c_1}{2}+\left(k-\frac{d}{2}\right)(l_1-l_2) \right)}
     \right)^{-1} -1\right], 
\end{equation*}
where $-l_1, -l_2$ are the Chern roots of the variables $c_1, c_2$, i.e. $c_1 = -l_1-l_2$ and $c_2 = l_1l_2$.

\label{convsubstitute}
We denote the class $\pi_{i_\ast}(h_i^k)$ by $\alpha_{i,k}(H)$ when we wish to regard it as a Chow class on $\mathbb P(W_{d}^{\oplus r+1})$, by $\alpha_{i,k}$  when we wish to regard it as a Chow class on $\mathcal M_{0}(\mathbb P^r, d)$, so that $\alpha_{i, k}=\alpha_{i,k}((d+1)c_1/2)$.
This convention extends to any other class with such double personality.

Let $\mathcal M_{0}(\mathbb P^r,d)$ be the category whose objects are diagrams
\[
\xymatrix{
C \ar[d]_{\pi}  \ar[r]^{f} & \mathbb P^r\\
S
}
\]
such that:
\begin{itemize}
\item $S$ is a $k$-scheme,
\item the morphism $\pi: C \to S$ is a projective flat family of curves isomorphic to $\mathbb P^1$,
\item the degree of $f^*\mathcal O_{\mathbb P^r}(1)$ on the geometric fibers of $\pi: C \to S$ is $d$.
\end{itemize}
As a consequence of the third bullet point,  the restriction of $f$ on the geometric fibers of $\pi: C \to S$ is in particular not constant. Arrows are cartesian diagrams:
\[
\xymatrix{
C_1 \ar @{} [dr] |{\Box} \ar[r]^{\psi} \ar[d]_{\pi_1} \ar@/^2.0pc/[rr]^{f_1=f_2 \circ \psi}& C_2 \ar[d]^{\pi_2}  \ar[r]^{f_2} & \mathbb P^r\\
S_1 \ar[r]^{\varphi}& S_2
}
\]

For every $i=1, \dots, d$, denote by  $Z_i$  the subspace of $\mathbb P \left( W_d^{\oplus r+1} \right)$ representing $(r+1)$-tuples of polynomials with a common factor of degree $i$, but not $i+1$:
\begin{equation}
 Z_i = \{(f_1, \ldots, f_{r+1}) | \deg(\gcd(f_1, \ldots, f_{r+1}) = i \}.
\end{equation}

\label{prop.equivariant.envelope}

Denote by $\widetilde{Z} := \bigsqcup_{i=1, \dots, d} \widetilde{Z}_i$ and by $\pi := \sqcup \pi_i$. 
Denoting by $\widetilde\pi$ the restriction of $\pi$ onto its image $\Delta_{r,d}$, we have that $$\widetilde\pi: \widetilde{Z}\to \Delta_{r,d}$$ is an equivariant envelope on $\Delta_{r,d}$.

\label{thmheresthepres}
For any odd positive integer $d$, and any integer $r\geq 0$ we have
\begin{equation}\label{gen.rel}
A^* \left( \mathcal M_{0}(\mathbb P^r, d) \right) \cong \frac{\mathbb Z[c_1,c_2]}{(\alpha_{i,k})_{i=1, \dots, d, k=0, \dots, i}}.\end{equation}

\label{lemma:coefficient-alpha-tilde}
Let $\widetilde{\alpha}_{a,k}$ be the class in $A^T_{*}(\mathbb P(W_i))$ defined in (\ref{modified:classes}). Then we have the following identity:
\[
\widetilde{\alpha}_{a,k}=\binom{i-k}{a-k} P_{i,k}(h_i) \]


\begin{dem}
Let $L_{a,k} \subset \mathbb P(W_a) \times \mathbb P(W_{i-a})$ be the locus of pairs of polynomials where the first one is a multiple of $y^k$. The locus $L_{a,k}$ is invariant for the action of the torus $T$ and its equivariant class is $P_{a,k}(h_a)$. The restriction of the map
\[
\pi_a: \mathbb P(W_a) \times \mathbb P(W_{i-a})
\]
to $L_{a,k}$ is finite of generic degree $\displaystyle \binom{i-k}{a-k}$ onto its image. This is due to the following facts:
\begin{itemize}
\item the image of $L_{a,k}$ is the locus of polynomials of degree $i$ which are divisible by $y^{k}$;
\item let $R(x,y)=y^k S(x,y)$ be a generic homogeneous polynomial of degree $i$ which is divisible by $y^k$.
Since we are in an algebraically closed field, and assuming by generality that $S(x,y)$  has $i-k$ distinct roots, there are exactly $\displaystyle \binom{i-k}{a-k}$ ways to choose a factor $F(x,y)$ of $S(x,y)$ of degree $a-k$ so that $[y^kF(x,y), S(x,y)/F(x,y)]$  in $\mathbb P(W_a) \times \mathbb P(W_{i-a})$ maps to $R(x,y)$.
\end{itemize}
To conclude the proof, we notice that $\left[L_{a,k} \right]=P_{a,k}(h_a)$ and $\left[\pi_{a}(L_{a,k}) \right]=P_{i,k}(h_i)$, therefore we have
\[
\widetilde{\alpha}_{a,k}=\binom{i-k}{a-k} P_{i,k}(h_i). \]
\end{dem}

\label{thm:genfunctionsforfirstenveloperelations}
For $k= 0,1$, consider the $A^* \left( \mathcal M_{0}(\mathbb P^r, d) \right)$ valued generating functions: 
$$
\mathcal{A}_{1,k}(c_1, c_2, d)  = \sum_{r=0}^{\infty} \pi_{1, \ast} [h_1^k] = \sum_{r=0}^{\infty} \alpha^{r}_{1,k},
$$
encoding the push-forwards of the fundamental class, and equivariant hyperplane class from the first component $Z_1$ of the envelope. We have:
\begin{equation}\label{eq:gf0}
  \mathcal{A}_{1,0}(c_1, c_2, d)  = \frac{d}{(1+\frac{d-1}{2}c_1)(1-\frac{d+1}{2}c_1)+d^2c_2} 
\end{equation}

\begin{equation}\label{eq:gf1}
 \mathcal{A}_{1,1}(c_1, c_2, d)  = \frac{1+\frac{d-1}{2}c_1}{(1+\frac{d-1}{2}c_1)(1-\frac{d+1}{2}c_1)+d^2c_2}-1.   
\end{equation}

We first establish some  conventions meant to simplify notation: the two  horizontal arrows of  diagram \eqref{eq:commdiagdimrr+1} are both denoted by $\pi_1$, and we will let the context determine which map any given equation is referring to. Similarly, the equivariant hyperplane classes for the three projective spaces in both rows of \eqref{eq:commdiagdimrr+1} are denoted $h_1,\eta_1$ and $H$ (as in Section \ref{sec:genrel}); each class in the top row is the pull-back of the corresponding class in the bottom row. So, for instance, any polynomial in $H, c_1, c_2$ denotes both a class for $\mathbb P(W_{d}^{\oplus r+2})$ and one for $\mathbb P(W_{d}^{\oplus r+1})$, with the latter being the pullback via $i_r$ of the former. 

The commutativity of the diagram \eqref{eq:commdiagdimrr+1} implies that for $k=0,1$:
\begin{equation}\label{eq:pushpush}
    i_{r\ast}(\pi_{1_{\ast}}(h_1^k)) =\pi_{1_{\ast}}((\text{id}\times i_r)_\ast(h_1^k)).
\end{equation}

Starting with the left hand side of \eqref{eq:pushpush}, $\pi_{1_{\ast}}(h_1^k) = \alpha^{r}_{1,k}(H)$ by definition, and by the projection formula one has
\begin{equation}\label{eq:LHS}
  i_{r_{\ast}}(\alpha^{r}_{1,k}(H)) =\alpha^{r}_{1,k}(H) P_d(H),
  \end{equation}
where $P_d(H) := P_{0,d}(H)$ from \eqref{eq:Prd}.

For the right hand side of \eqref{eq:commdiagdimrr+1}, we  apply the projection formula to obtain
\begin{equation}
 \pi_{1_{\ast}}((\text{id}\times i_r)_\ast(h_1^k)) = h_1^k P_{d-1}(\eta_1).   
\end{equation}
Using that $H = h_1+\eta_1$ (where we omit $\pi_1^\ast$ from the notation for the pullback of the class $H$), and the presentation of the equivariant Chow ring of $\mathbb P(W_1)$, we may write
\begin{equation}\label{eq:remainder}
  h_1^k P_{d-1}(\eta_1) = R_{1,k,0}^{r,d}(H,c_1, c_2)+ R_{1,k,1}^{r,d}(H,c_1,c_2)h_1,   
\end{equation}
where the right hand side of \eqref{eq:remainder} is the remainder of the division of $P_{d-1}(H-h_1)$ by the polynomial
$P_{1}(h_1)=(h_1^2- c_1h_1 +c_2)$.

Pushing forward and using the projection formula, we then obtain:
\begin{equation}
 \pi_{1_{\ast}}((\text{id}\times i_r)_\ast(h_1^k)) = R_{1,k,0}^{r,d}(H,c_1, c_2)\alpha^{r+1}_{1,0}(H)+ R_{1,k,1}^{r,d}(H,c_1,c_2)\alpha^{r+1}_{1,1}(H).   
\end{equation}

From equations \eqref{eq:commdiagdimrr+1},\eqref{eq:LHS} and \eqref{eq:remainder}, by substituting $H= \frac{d+1}{2} c_1$ one obtains the square size $2$ linear system
\begin{equation}\label{eq:linsys}
 P_d \alpha_{1,k}^{r} = R_{1,k,0}^{r,d}\alpha^{r+1}_{1,0}+ R_{1,k,1}^{r,d}\alpha^{r+1}_{1,1},\end{equation}
where $k = 0,1$.

We observe that all coefficients in  \eqref{eq:linsys} are divisible by $P_{d-2}:=P_{d-2}\left(\frac{d-1}{2}c_1\right).$


\begin{claim}\label{claim:identities}

We have the following identities:
\begin{eqnarray}
\label{eq:PdQd}P_d &=& \left(
d^2 c_2-\frac{d^2 -1}{4} c_1^2 
\right)P_{d-2}\\
\label{eq:R100}R_{1,0,0}^{r,d} &=&  \left(
\frac{d+1}{2} c_1
\right) P_{d-2}\\
\label{eq:R101}R_{1,0,1}^{r,d} &=&  
-d P_{d-2}\\
\label{eq:R110}R_{1,1,0}^{r,d} &=&  dc_2P_{d-2}\\
\label{eq:R111}R_{1,1,1}^{r,d} &=&  \left(
\frac{1-d}{2}c_1
\right)P_{d-2}
\end{eqnarray}
\end{claim}

Using the results from Claim \ref{claim:identities}, proved at the end of the section, the linear system \eqref{eq:linsys} simplifies to
\begin{equation}\label{eq:linsysmatform}
\left(
d^2 c_2-\frac{d^2 -1}{4} c_1^2 
\right)\left[
\begin{array}{c}
\alpha^{r}_{1,0}\\
\alpha^{r}_{1,1}
\end{array}
\right] = 
\left[
\begin{array}{cc}

\frac{d+1}{2} c_1
 & -d\\
 d c_2 & 
\frac{1-d}{2}c_1

\end{array}
\right]
\left[
\begin{array}{c}
\alpha^{r+1}_{1,0}\\
\alpha^{r+1}_{1,1}
\end{array}
\right]
\end{equation}
The linear system \eqref{eq:linsysmatform} may be solved for the $\alpha_{1,k}^{r+1}$'s to obtain:
\begin{eqnarray}\label{eq:linsyssolut}
\alpha^{r+1}_{1,0}
&=&
\frac{1-d}{2}c_1\alpha^{r}_{1,0}+
d \alpha^{r}_{1,1}
\nonumber
\\
\alpha^{r+1}_{1,1}
&=&
-d c_2\alpha^{r}_{1,0}+
\frac{d+1}{2}c_1\alpha^{r}_{1,1}.
\end{eqnarray}

Together with the initial conditions
\begin{equation}\label{eq:initcondit}
 \alpha_{1,0}^{0} = d, \ \ \   \alpha_{1,1}^{0} = \frac{d+1}{2}c_1,
\end{equation}
the equations in \eqref{eq:linsyssolut} for all $r\geq 0$ determine recursively 
all values of $\alpha_{1,k}^{r}$.
To conclude the proof, it suffices to observe that \eqref{eq:linsyssolut}
and \eqref{eq:initcondit} give rise to the system of functional equations:
\begin{equation}
\label{eq:funsyssolut}    
\left\{
\begin{array}{ccc}
\mathcal{A}_{1,0}-d
&=&
\frac{1-d}{2}c_1\mathcal{A}_{1,0}+
d \mathcal{A}_{1,1}
\\
\mathcal{A}_{1,1} - \frac{d+1}{2}c_1
&=&
-d c_2\mathcal{A}_{1,0}+
\frac{d+1}{2}c_1\mathcal{A}_{1,1},
\end{array}
\right.
\end{equation}
together with the boundary conditions
\begin{equation}\label{eq:boundaryconditions}
    \mathcal{A}_{1,0}(0,0,d)  = d, \ \ \ \ \mathcal{A}_{1,1}(0,0,d)  = 0.
\end{equation}
It is then immediate to verify that \eqref{eq:funsyssolut},\eqref{eq:boundaryconditions} are satisfied by the generating functions \eqref{eq:gf0},\eqref{eq:gf1}. Thus Theorem \ref{thm:genfunctionsforfirstenveloperelations} is proved (as soon as the identities from Claim \ref{claim:identities} are established).

\label{thm:degszero} 

For any $d>0, r\geq 0, 0\leq i \leq d$, the relations $\alpha_{i,0}\in A^\ast(\mathcal M_{0}(\mathbb P^r, d))$ are given by the formula:
\begin{equation}\label{eq:closedformzerorel}
\alpha_{i,0}=
     \displaystyle \sum_{j=0}^{i} \frac{(-1)^{j}}{i! (l_2-l_1)^i}\binom{i}{j}\left(\frac{P_{d}}
     {\prod_{k = j}^{d-i+j}\left(\frac{c_1}{2}+\left(k-\frac{d}{2}\right)(l_2-l_1) \right)}
     \right)^{r+1}.  
\end{equation}

Referring to diagram
\eqref{eq:projsone} for notation,  we compute 
\begin{equation}
    \alpha_{i,0} = \pi_{1_{\ast}}([\widetilde{Z}_i]) = \pi_{1_{\ast}}(p_1^\ast([\mathbb P(W_i)]))
\end{equation}
by first localizing the fundamental class of $[\mathbb P(W_i)]$ and then pull-pushing the corresponding expression taking advantage of the fact that it is supported on a torus invariant subvariety. 

For $0\leq j\leq i$, denote by $q_j$ the  torus invariant point where only the $j$-th homogeneous coordinate is non-zero. From Theorem \ref{thm.loc} we have
\begin{equation}
  [\mathbb P(W_i)] = \sum_{j=0}^i \frac{[q_j]}{e(N_{q_j/\mathbb P(W_i)})},
\end{equation}
where the equivariant Euler class of the normal bundle to $q_j$ is the product of the $i$ tangent weights 
\begin{equation}
e(N_{q_j/\mathbb P(W_i)}) = 
\prod_{k\not=j}[((i-k) l_1+ kl_2)-((i-j) l_1+j l_2)] = (-1)^jj!(i-j)!(l_2-l_1)^i.
\end{equation}
Since both $p_1^\ast$ and $\pi_{1_{\ast}}$ are morphisms of $\mathcal Q$ modules, we have
\begin{equation}\label{eq:kicaku}
  \pi_{1_{\ast}}(p_1^\ast([\mathbb P(W_i)])) = \sum_{j=0}^i (-1)^j\frac{\pi_{1_{\ast}}[q_j\times \mathbb P(W_{d-i}^{\oplus r+1})]}{j!(i-j)!(l_2-l_1)^i}  
\end{equation}

It remains to compute the equivariant Chow class of $\pi_{1_{\ast}}[q_j\times \mathbb P(W_{d-i}^{\oplus r+1})]$. One may see that $\pi_1$ maps the subspace $q_j\times \mathbb P(W_{d-i}^{\oplus r+1})$ isomorphically onto the linear subspace of $\mathbb P(W_{d}^{\oplus r+1})$ parameterizing  $(r+1)$-tuples of polynomials which are divisible by $x^j$ and $y^{i-j}$. The class of this subspace corresponds to the product of the linear factors of the polynomial $P_{r,d}(H)$ corresponding to the homogeneous coordinates that vanish. By equivalently dividing $P_{r,d}(H)$ by the factors corresponding to the coordinates that do not vanish, one may write:


\begin{equation} \label{eq:pushfwdallway}
  \pi_{1_{\ast}}[q_j\times \mathbb P(W_{d-i}^{\oplus r+1})]   

  = \frac{P_{r,d}(H)}{\prod_{k=j}^{d-i+j} (H+(d-k)l_1+kl_2)^{r+1} } 
\end{equation}
Plugging \eqref{eq:pushfwdallway} into \eqref{eq:kicaku} and substituting $H= \frac{d+1}{2} c_1$ one readily obtains the expression in \eqref{eq:closedformzerorel}.

\label{cor:diffop}
For any fixed values of $r,d>0$, the relations $ \alpha_{i,0}$ for all values of $i$ are encoded in the generating function:
\begin{equation}\label{eq:genfunzerorel}
 \mathcal{A}_{0}(d) =   \sum_ {i =0}^d \alpha_{i,0}  =\left[ 
\left(
\text{e}^{t_1\partial_x+t_2\partial_y}
\left(
x^{\frac{c_1}{2(l_1-l_2)}+\frac{d}{2}}
y^{\frac{c_1}{2(l_2-l_1)}+\frac{d}{2}}
\right)
\right)^{\odot r+1}_{|x=y=1}
\right]_{\left | t_1 =t_2=1, \; deg \leq dr \right.},
\end{equation}
where the symbol $\odot$ refers to a Hadamard power for a two-variable exponential power series in variables $t_1/(l_1-l_2), t_2/(l_2-l_1)$,  defined as follows:
\begin{equation}\label{hadamard}
\left(\sum_{\mu,\nu} a_{\mu,\nu}  \frac{\left(\frac{t_1}{l_1-l_2}\right)^\mu}{\mu!}\frac{\left(\frac{t_2}{l_2-l_1}\right)^\nu}{\nu!}\right)^{\odot r+1}  :=  \sum_{\mu,\nu} a_{\mu,\nu}^{r+1}  \frac{\left(\frac{t_1}{l_1-l_2}\right)^\mu}{\mu!}\frac{\left(\frac{t_2}{l_2-l_1}\right)^\nu}{\nu!}.
\end{equation}

We    show that the degree $ri$ summand  of \eqref{eq:genfunzerorel} coincides with  \eqref{eq:closedformzerorel}.

The exponential differential operator is in commuting variables and hence it admits the natural Taylor expansion:
\begin{equation}\label{eq:expdiffop}
    \text{e}^{t_1\partial_x+t_2\partial_y} = \sum_{\mu, \nu}\frac{t_1^\mu}{\mu!}\frac{t_2^\nu}{\nu!}\partial_x^\mu\partial_y^\nu
\end{equation}
Applying the general summand in \eqref{eq:expdiffop} to the monomial 
$\left(
x^{\frac{c_1}{2(l_1-l_2)}+\frac{d}{2}}
y^{\frac{c_1}{2(l_2-l_1)}+\frac{d}{2}}
\right)$ and specializing $x=y=1$ one obtains:
\begin{equation} \label{eq:pakjdjhsd}
    \frac{t_1^\mu}{\mu!}\frac{t_2^\nu}{\nu!}\frac{(-1)^\mu}{(l_2-l_1)^{\mu+\nu}}
    \prod_{k=0}^{\mu-1} \left(\frac{c_1}{2}+\left(k-\frac{d}{2}\right)(l_2-l_1)\right)\prod_{m=0}^{\nu-1}\left(\frac{c_1}{2}+\left(\frac{d}{2}-m\right)(l_2-l_1)\right)
\end{equation}
Reindexing the second product in \eqref{eq:pakjdjhsd} by $m = d-k$ one may rewrite \eqref{eq:pakjdjhsd} to obtain
\begin{equation}
=\sum_{\mu,\nu}\label{eq:pakjd}
    \frac{t_1^\mu}{\mu!}\frac{t_2^\nu}{\nu!}\frac{(-1)^\mu}{(l_2-l_1)^{\mu+\nu}}
\frac{P_d}{
    \prod_{k=\mu}^{d-\nu+1} 
    \left(\frac{c_1}{2}+\left(k-\frac{d}{2}\right)(l_2-l_1)\right)}
\end{equation}
By the definition of Hadamard power in \eqref{hadamard}, taking the $(r+1)$-th power of the power series in \ref{eq:pakjd} has the effect of raising the last rational function to the power of $(r+1)$.
The Chow degree of the coefficient of $t_1^\mu t_2^\nu$ is $(r+1)(\mu+\nu) - (\mu+\nu) = r(\mu+\nu)$, from which follows that the degree $ri$ coefficient of the series is obtained by summing over all non-negative pairs of values of $\mu$ and $\nu$ adding to $i$. Setting $\mu = j, \nu = i-j$ one may immediately recognize formula \eqref{eq:closedformzerorel}.
